insert into averra_super_curriculum (year_group_code,subject_code,subject,topics,source_contributions,competencies)
values ('Reception','MATH','Mathematics',
$topics$[{"name": "Number and Early Mathematical Thinking", "topics": [{"name": "Counting and Cardinality", "subtopics": ["Counting objects 1 to 20 with one-to-one correspondence", "Subitising quantities to 5 without counting", "Reading and writing numerals 0 to 20", "Comparing groups: more, fewer, same", "Number before and after"]}, {"name": "Composition of Number", "subtopics": ["Number bonds to 5 and 10", "Splitting numbers into parts: part-part-whole", "Odd and even introduction through grouping", "Doubles to 5"]}, {"name": "Pattern and Structure", "subtopics": ["Repeating patterns: AB, AAB, ABB", "Copying, continuing and creating patterns", "Recognising patterns in the environment", "Number patterns: skip counting in 2s and 10s"]}]}, {"name": "Shape, Space and Measure", "topics": [{"name": "Geometry", "subtopics": ["Naming and describing 2D shapes: circle, triangle, square, rectangle", "Naming and describing 3D shapes: sphere, cube, cylinder, cone", "Sorting shapes by attribute", "Positional language: inside, outside, next to, between, above, below"]}, {"name": "Measurement", "subtopics": ["Comparing and ordering by length, height, weight and capacity", "Direct comparison of two objects", "Sequencing daily events", "Days of the week in order", "Understanding morning, afternoon, evening, night"]}]}, {"name": "Early Problem Solving", "topics": [{"name": "Mathematical Reasoning", "subtopics": ["Explaining thinking using mathematical language", "Noticing and describing mathematical patterns", "Simple real-life problems involving combining and separating", "Using objects and pictures to represent problems"]}]}]$topics$,
$source${"England (DfE EYFS)": ["One-to-one correspondence counting", "Subitising to 5", "Number composition to 10"], "Finland (FNAE)": ["Play-based number exploration", "Pattern recognition through creative activities"], "Japan (MEXT)": ["Deep understanding through manipulation of concrete objects", "Mathematical language emphasis from early age"], "Singapore (MOE)": ["Number bonds approach to composition", "Structured concrete-pictorial-abstract progression"], "Estonia (MoE)": ["Digital literacy integrated: introduction to simple patterns in computing context"], "Canada (Ontario)": ["Inquiry-based mathematical thinking", "Real-world problem contexts"], "Nigeria (NERDC)": ["Cultural counting games and number songs", "Local context money and measurement examples"]}$source$,
$comp${"by_end_of_year": ["Count reliably to 20 with one-to-one correspondence", "Subitise quantities to 5", "Compose and decompose numbers to 10", "Recognise, copy and create repeating patterns", "Name common 2D and 3D shapes", "Compare objects by length, weight and capacity"]}$comp$)
