$topics$[{"name": "Number", "topics": [{"name": "Integers, Powers and Roots", "subtopics": ["Operations with positive and negative integers", "Powers and roots: squares, cubes, square roots, cube roots", "Index notation and laws of indices (introduction)", "Prime factorisation: factor trees and Venn diagrams", "LCM and HCF using prime factorisation", "Standard form: large and small numbers"]}, {"name": "Fractions, Decimals and Percentages", "subtopics": ["All operations with fractions \u2014 fluency", "Recurring decimals: converting to fractions", "Percentage change and reverse percentage", "Compound interest and depreciation", "VAT and financial applications", "Ratio and proportion: all problem types"]}]}, {"name": "Algebra", "topics": [{"name": "Expressions and Equations", "subtopics": ["Algebraic notation and conventions", "Collecting like terms", "Expanding single brackets", "Factorising by taking out common factor", "Solving linear equations with unknowns on both sides", "Forming and solving equations from word problems", "Substitution into formulae", "Changing the subject of a formula"]}, {"name": "Sequences", "subtopics": ["Describing sequences using term-to-term rule", "nth term of arithmetic sequences", "Generating sequences from nth term", "Geometric sequences \u2014 recognising and describing", "Fibonacci and other famous sequences"]}]}, {"name": "Ratio and Proportion", "topics": [{"name": "Ratio and Proportion", "subtopics": ["Simplifying ratios", "Dividing in a ratio", "Best value problems", "Direct proportion: y = kx", "Inverse proportion: y = k/x", "Speed, distance, time calculations", "Density, mass, volume calculations", "Map scales and scale drawings"]}]}, {"name": "Geometry", "topics": [{"name": "Angles", "subtopics": ["Angles in parallel lines: alternate, co-interior, corresponding", "Angles in polygons: interior and exterior", "Bearings", "Constructions: perpendicular bisector, angle bisector, triangles"]}, {"name": "Area and Perimeter", "subtopics": ["Area of all standard shapes", "Circumference and area of circles", "Arc length and sector area", "Area of compound shapes", "Perimeter of compound shapes"]}, {"name": "3D Shapes", "subtopics": ["Volume of prisms and cylinders", "Surface area of prisms and cylinders", "Nets of 3D shapes", "Cross-sections"]}]}, {"name": "Statistics and Probability", "topics": [{"name": "Statistics", "subtopics": ["Mean, median, mode and range \u2014 calculation and comparison", "Grouped frequency tables", "Bar charts and histograms (equal class widths)", "Pie charts", "Scatter graphs: positive, negative and no correlation", "Line of best fit: drawing and using", "Two-way tables"]}, {"name": "Probability", "subtopics": ["Probability scale 0 to 1", "Mutually exclusive events", "Complement rule", "Sample space diagrams", "Experimental vs theoretical probability", "Relative frequency"]}]}]$topics$,
$source${"England (DfE GCSE foundation)": ["Algebra: expressions, equations, sequences", "Angles in parallel lines", "Scatter graphs and correlation"], "Singapore (MOE Secondary 1)": ["Ratio and proportion: systematic model method", "Algebraic problem solving", "Statistical analysis"], "Japan (MEXT Junior High 1)": ["Mathematical proof and justification", "Functions: input-output thinking", "Geometric constructions"], "Finland (FNAE Grade 7)": ["Statistics from real-world data", "Environmental applications of ratio", "Critical evaluation of mathematical models"], "Canada (Ontario Grade 7-8)": ["Financial literacy: compound interest", "Algebraic thinking for all", "Growth mindset: productive struggle"], "Estonia (MoE Grade 7)": ["Coding with algebraic logic", "Data analysis with digital tools", "Computational problem solving"], "Nigeria (NERDC JSS 1-2)": ["Number bases for computing context", "Commercial arithmetic", "Geometric constructions"]}$source$,
$comp${"by_end_of_year": ["Work confidently with all integer operations and apply index laws", "Solve linear equations including with unknowns on both sides", "Find the nth term of arithmetic sequences", "Apply ratio, proportion and percentage to complex real-life problems", "Calculate arc length, sector area, and volumes of prisms", "Interpret scatter graphs and calculate relative frequency"]}$comp$)
